DEEP=[
D('The road ___ repaired at the moment.','is being',{'is been':'been, be fiilinin V3 hâlidir ve "has/have/had" ile birlikte kullanılır; süren pasif için is being gerekir (at the moment = şu an).'}),
D('The results ___ announced tomorrow.','will be',{'will':'will + V3 yapısı pasif olmaz; pasif için araya be girer: will be announced.','will being':'will'+'dan sonra yalın fiil gelir (be); being sürekli bir yapıdır ve burada kalıp bozulur.'}),
D('This form must ___ signed.','be',{'been':'Modalden sonra yalın fiil gelir; been bir V3 biçimidir ve modalden sonra kullanılmaz (must be signed).'}),
D('The thief ___ caught before we arrived.','had been',{'has being':'has being yapısı diye bir kalıp yoktur; "biz gelmeden önce" geçmişteki önceliği anlattığı için Past Perfect pasif: had been caught.'}),
D('The house ___ painted when we visited.','was being',{'is being':'visited geçmiş zamanda; is being şimdiki zaman olur. Geçmişte süren pasif: was being.','was been':'was ile been birlikte kullanılmaz; süren eylem için was being, tamamlanmış için had been kullanılır.'}),
D('Has the email ___ sent yet?','been',{'be':'Has ile birlikte V3 gerekir: has been sent. Yalın be, Has ile pasif oluşturmaz.','being':'being "-yor/-iliyor" anlamlı sürekli pasiftir; yet ile kurulan Present Perfect pasifte been gelir.'}),
D('The meeting might ___ postponed.','be',{'been':'Modalden sonra yalın fiil gelir: might be postponed. been, have ile birlikte kullanılır (might have been postponed).'}),
D('They gave me a prize. → I ___ a prize.','was given',{'gave':'gave etken biçimdir: "ben verdim" olurdu. Ödülü alan taraf özne olunca pasif gerekir: was given.','was give':'was'+'dan sonra V3 gelir: give → gave → given. "give" yalın hâldir.'}),
D('It ___ said that he is very rich.','is',{'has':'It has said diye bir pasif kalıp yoktur; pasif için be + V3 gerekir: It is said.','does':'does ile pasif kurulmaz; pasif be fiili ister (It is said that ...).'}),
D('He is believed ___ in Paris.','to be',{'being':'is believed + being yapısı kalıbı bozar; "inanılıyor ki ... " için is believed to + fiil kullanılır.','be':'is believed ... be şeklinde to düşmez; to be gerekir.'}),
D('The parcel is going to ___ delivered tomorrow.','be',{'being':'going to + yalın fiil gelir; being -ing biçimidir ve burada yanlıştır.','been':'going to'+'dan sonra yalın fiil gerekir; been V3 olduğu için kullanılamaz.'}),
D('"They are building a new bridge." Pasifi hangisi?','A new bridge is being built.',{'A new bridge is built.':'is built süreç anlamını (şu an inşa ediliyor) kaybettirir ve basit geniş zaman pasifi olur.','A new bridge has being built.':'has being diye bir kalıp yoktur; Present Continuous pasifi is being + V3\'tür.'}),
D('"They have cancelled the match." Pasifi hangisi?','The match has been cancelled.',{'The match was being cancelled.':'was being geçmişte süren eylemi anlatır; have cancelled (Present Perfect) için has been cancelled gerekir.','The match has cancelled.':'has cancelled etken yapıdır ve maçın kendini iptal ettiğini ima eder; pasif için been gerekir.'}),
D('Hangi cümle doğru?','Mobile phones must be switched off.',{'Mobile phones must switched off.':'Pasifte modalden sonra be gerekir; be eksik.','Mobile phones must being switched off.':'Modalden sonra yalın fiil gelir; being doğru değil: must be switched off.'}),
D('Hangi cümle doğru?','She was offered a job.',{'She was offer a job.':'was'+'dan sonra V3 gelir: offered.'}),
D('Hangi cümle doğru?','The castle is said to be haunted.',{'The castle says to be haunted.':'Şato kimseye bir şey söylemez; "söyleniyor" anlamı pasifle verilir: is said.','The castle is said that it is haunted.':'is said that yapısı yalnızca "It" ile kurulur (It is said that the castle is haunted); özne castle ise is said to be kullanılır.'}),
D('Hangi cümle "Çalınmış olmalı" demektir?','It must have been stolen.',{'It must be stolen.':'must be stolen şimdiki durumu anlatır (çalınmak zorunda); geçmişe dönük çıkarım için must have been stolen.'}),
D('Hangi cümle doğru? (kaçtığına inanılıyor)','He is believed to have escaped.',{'He believed to have escaped.':'believed etkendir: "o inandı" olurdu; "inanılıyor" için pasif gerekir: is believed.','He is believed to escape yesterday.':'yesterday geçmişi gösterir; to escape yalın biçimdir. Geçmişe dönük: to have escaped.'}),
]
